pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if let Some(payload) = bytes.strip_prefix("v:2;hello:") {
        return Ok(Msg::Hello(payload.into()));
    }
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    eprintln!("protocol decode error: unknown message");
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(payload) => format!("v:2;hello:{payload}"),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn ping_encode_roundtrip() {
        let decoded = decode(&encode(&Msg::Ping)).expect("encoded ping should decode");
        assert!(matches!(decoded, Msg::Ping));
    }

    #[test]
    fn hello_encode_roundtrip() {
        let decoded = decode(&encode(&Msg::Hello("client".into())))
            .expect("encoded hello should decode");
        assert!(matches!(decoded, Msg::Hello(payload) if payload == "client"));
    }

    #[test]
    fn hello_has_v2_envelope() {
        assert_eq!(encode(&Msg::Hello("client".into())), "v:2;hello:client");
    }
}
